/**
 * Elevation difference between two registered DEM sources, as a colour tile.
 *
 * WHY
 * ---
 * Two surveys of the same ground answer questions a single hillshade cannot:
 * where did material move, and do the two agree at all? The same picture
 * settles both. Real change is patchy and sits where the ground can move --
 * a slump scar, a delta, a migrating bedform. A survey-wide constant tint is
 * not change; it is a vertical datum disagreement, which is exactly how the
 * 2019 Seldovia delivery was caught sitting 1.42 m below its neighbour.
 *
 * COLOUR (Hig, 2026-09-14)
 * ------------------------
 * ColorBrewer PRGn, oriented by TIME rather than by which layer is on top:
 * green where the ground rose between the older survey and the newer one,
 * purple where it fell. Red/blue is avoided deliberately -- its reading flips
 * between disciplines (hot/cold, cut/fill, positive/negative), while nobody
 * reads green as "lower". The caller is responsible for passing the newer
 * survey as the tile's own source and the older one as `diff`, so the sign
 * here is always newer minus older.
 *
 * White is the middle of PRGn, so a tile of genuinely unchanged ground reads
 * as near-transparent tint over the hillshade rather than as a colour.
 */
import { buildLut, LUT_N } from './shade';
import type { RampStop } from './types';

/** ColorBrewer PRGn, 11-class, purple (fell) -> white (unchanged) -> green (rose). */
export const PRGN_STOPS: RampStop[] = [
  [-1.0, 0x40, 0x00, 0x4b],
  [-0.8, 0x76, 0x2a, 0x83],
  [-0.6, 0x99, 0x70, 0xab],
  [-0.4, 0xc2, 0xa5, 0xcf],
  [-0.2, 0xe7, 0xd4, 0xe8],
  [0.0, 0xf7, 0xf7, 0xf7],
  [0.2, 0xd9, 0xf0, 0xd3],
  [0.4, 0xa6, 0xdb, 0xa0],
  [0.6, 0x5a, 0xae, 0x61],
  [0.8, 0x1b, 0x78, 0x37],
  [1.0, 0x00, 0x44, 0x1b],
];

/** The PRGn ramp as a lookup table over normalised difference -1..+1. */
export const PRGN_LUT: Uint8Array = buildLut(PRGN_STOPS, -1, 1);

/**
 * Colour one tile from two elevation grids of the same size.
 *
 * @param newer  elevations of the later survey, NaN where it has no data
 * @param older  elevations of the earlier survey, NaN where it has no data
 * @param dmax   metres at which the ramp saturates; differences beyond clamp
 * @returns RGBA, transparent wherever either survey is missing
 *
 * Transparency is the honest answer for a one-sided pixel: "no comparison
 * here" is not "no change here", and painting it white would claim agreement
 * the data cannot support. That also makes the layer self-masking -- it draws
 * exactly the overlap of the two surveys and nothing else.
 */
export function shadeDiff(newer: Float32Array, older: Float32Array, dmax: number): Uint8ClampedArray<ArrayBuffer> {
  const n = newer.length;
  const px = new Uint8ClampedArray(new ArrayBuffer(n * 4));
  const scale = dmax > 0 ? 1 / dmax : 0;
  for (let i = 0; i < n; i++) {
    const a = newer[i];
    const b = older[i];
    // NaN fails every comparison, so this rejects a missing value on either side.
    if (!(a === a) || !(b === b)) continue;
    let t = (a - b) * scale;
    t = t < -1 ? -1 : t > 1 ? 1 : t;
    const k = Math.round(((t + 1) / 2) * (LUT_N - 1)) * 3;
    const o = i * 4;
    px[o] = PRGN_LUT[k];
    px[o + 1] = PRGN_LUT[k + 1];
    px[o + 2] = PRGN_LUT[k + 2];
    px[o + 3] = 255;
  }
  return px;
}
